           //get image graphics to test drawing            Graphics g = Graphics.FromImage(pictureBox1.Image);            // create edges around shape            SplineDots.ForEach((d, i) => {                if (i < SplineDots.Count() - 2) {                    Point p1 = GlobalToLocal(d.Location);                    Point center = GlobalToLocal(SplineDots[i + 1].Location);                    Point p2 = GlobalToLocal(SplineDots[i + 2].Location);                    var v1 = new Vector2D(center.X - p1.X, center.Y - p1.Y);                    var v2 = new Vector2D(center.X - p2.X, center.Y - p2.Y);                    var v3 = new Vector2D(p1.X - p2.X, p1.Y - p2.Y);                    var a2 = Vector2D.AngleBetween(v2, v3);                    var distP2P3 = Math.Cos((Math.PI / 180) * a2) * v2.Length;                    v3.Length = distP2P3;                    var p3 = v3.Clone().Add(p2).ToPoint();                    var v4 = new Vector2D(center.X - p3.X, center.Y - p3.Y) {                        Length = offset                    };                    // reverse vector if angle is negative                    var a1 = Vector2D.AngleBetween(v1.Clone().Invert(), v2.Clone().Invert());                    if (a1 < 0) v4.Invert();                    //v1.DrawFrom(g, p1, 2, Color.Green);                    //v2.DrawFrom(g, p2, 2, Color.Blue);                    //v3.DrawFrom(g, p2, 2, Color.Red);                    v4.Draw(g, center, 2, Color.Purple);                }            });            pictureBox1.Refresh();